SELECT id, symbol, status, started_at, last_evidence_at, anchor_entry_price, best_entry_price, latest_signal_id, evidence_count, buy_count, watch_count, neutral_count, bearish_count, evidence_score, opportunity_health, five_minute_decision, one_hour_decision, execution_source, recommended_position_percent, decision_code, executed_at FROM crypto_ai.execution_opportunity WHERE (symbol = 'EGLDUSDT' AND last_evidence_at BETWEEN '2026-10-11 20:00:00' AND '2026-10-11 22:41:00') OR (symbol = 'XRPUSDT' AND last_evidence_at BETWEEN '2026-10-12 01:30:00' AND '2026-10-12 02:36:00') OR (symbol = 'DOGEUSDT' AND last_evidence_at BETWEEN '2026-10-12 03:00:00' AND '2026-10-12 04:03:00') OR (symbol = 'SHIBUSDT' AND last_evidence_at BETWEEN '2026-10-12 05:30:00' AND '2026-10-12 06:37:00') OR (symbol = 'ACEUSDT' AND last_evidence_at BETWEEN '2026-10-12 09:00:00' AND '2026-10-12 09:58:00') ORDER BY symbol, last_evidence_at LIMIT 200;